    <article class="metric"><span class="metric-label">Sản phẩm</span><strong><?= number_format($totalProducts) ?><small> sản phẩm</small></strong><span class="metric-note">Danh mục & linh kiện</span></article>
    <article class="metric"><span class="metric-label">Khách hàng</span><strong><?= number_format($totalUsers) ?><small> tài khoản</small></strong><span class="metric-note">Khách hàng đã đăng ký</span></article>
